INSERT INTO `movies` (`movie_id`, `genre_id`, `title`, `duration`, `director`, `cast`, `release_date`, `end_date`, `poster`, `trailer`, `age_rating`, `language`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`, `format`) VALUES
(29, 18, 'IT FEEDS: QUỶ ĂN HỒN', 102, 'Chad Archibald', 'Ellie O\'Brien, Ashley Greene', '2025-07-25', '2025-08-25', 'posters/referenceschemeheadofficeallowplaceholdertrueheight700ldapp-24_1753248869.jpg', NULL, 'T18', 'Tiếng Việt', 'Sau khi một cô gái trẻ xông vào phòng khám tâm thần tại nhà của họ và tuyên bố rằng có một thực thể đang ăn thịt cô, Jordan và người mẹ có năng lực thấu thị của cô phải tìm cách ngăn chặn thế lực đó trước khi cô gái bị bắt đi hoàn toàn.', 'active', '2025-07-22 22:34:29', '2025-08-01 21:46:28', NULL, '2D'),
(31, 22, 'BEHIND THE SHADOWS: THÁM TỬ TƯ: PHÍA SAU VẾT MÁU', 103, 'Man Yu Chow, Jonathan Li', 'Kuan-Ting Liu, Louis Koo', '2025-07-23', '2025-08-21', 'posters/referenceschemeheadofficeallowplaceholdertrueheight700ldapp_1753279763.jpg', 'https://www.youtube.com/watch?v=sUwivH5Vv5w', 'T13', 'Phụ đề', 'Phim kể về câu chuyện của thám tử tư Âu Dương Huệ Nghi, người chiến đấu để điều tra sự thật về một vụ án chưa được giải quyết.', 'active', '2025-07-23 07:09:23', '2025-07-23 07:09:23', NULL, '2D'),
(32, 19, 'MARACUDA: NHÓC QUẬY RỪNG XANH', 89, 'Victor Glukhushin', 'Arbani Yasiz, Ersya Aurelia', '2025-07-11', '2025-09-01', 'posters/referenceschemeheadofficeallowplaceholdertrueheight700ldapp-5_1753364328.jpg', 'https://www.youtube.com/watch?v=iaOM-lHCCtI', 'P', 'Tiếng Việt', 'Maracuda – cậu bé không giỏi chiến đấu – phải vào rừng cổ đại để chứng minh mình là một chiến binh thật sự. Cùng chú chim Tink lanh lợi và thỏ Stomp vụng về, cậu bước vào chuyến phiêu lưu kỳ lạ, đối đầu quái vật và hiểm nguy.', 'active', '2025-07-24 06:38:48', '2025-08-01 19:32:19', NULL, '2D'),
(33, 19, 'LOVESICK: TÔI CÓ BỆNH MỚI THÍCH CẬU', 110, 'Hsu Fu Hsiang', 'Zhan Huai Yun, Chiang Chi', '2025-08-15', '2025-10-01', 'posters/cig37plrl6v4xatjv3hroq6c50nz1cqi_1754104850.jpg', 'https://www.youtube.com/watch?v=Lat8G88hzqs', 'P', 'Phụ đề', 'Phim kể về Ji Zie, cô gái sống khép kín, cho đến khi gặp lại người bạn cũ. Dần dần, họ trở nên thân thiết, chia sẻ những kỷ niệm tuổi học trò đầy hoài niệm và cảm xúc. Bộ phim khắc họa tình bạn chân thành và những khoảnh khắc ngọt ngào của thời học sinh.', 'active', '2025-08-01 20:20:50', '2025-08-01 20:20:50', NULL, '2D'),
(34, 19, 'HELLO JADOO: LẠC VÀO VƯƠNG QUỐC PHÉP THUẬT', 115, 'Huwng', NULL, '2025-08-29', '2025-10-02', 'posters/referenceschemeheadofficeallowplaceholdertrueheight700ldapp-17_1754104917.png', NULL, 'P', 'Tiếng Việt', 'Jadoo, một cô bé kỳ lạ bị hiểu lầm và đuổi khỏi làng, tìm đến võ đường để rèn luyện. Cô từng chỉ mong được sống yên bình cùng mọi người. Khi ngôi làng cũ bị quái vật tấn công, cô phải chọn giữa oán giận và tha thứ để trở thành người hùng.', 'active', '2025-08-01 20:21:57', '2025-08-14 01:48:42', NULL, '2D'),
(35, 16, 'DEMON SLAYER: THANH GƯOM DIỆT QUỶ: VÔ HẠN THÀNH', 155, 'Haruo Sotozaki', NULL, '2025-08-14', '2025-10-16', 'posters/muzan_1755161625.jpg', 'https://www.youtube.com/watch?v=f0bZNO6KKH8', 'T13', 'Tiếng Việt', 'Sát Quỷ Đoàn xông vào Vô Hạn Thành để đánh bại Muzan. Tuy nhiên, những Trụ Cột còn lại và những thành viên Sát Quỷ Đoàn sống sót sau khóa đào tạo cuối cùng và Tanjiro phải đối đầu với nhóm cuối trong Thập Nhị Quỷ trước.', 'active', '2025-08-14 01:53:45', '2025-08-14 01:54:38', NULL, 'IMAX'),
(36, 19, 'SHINCHAN: NHỮNG VŨ CÔNG SIÊU CAY KASUKABE', 105, 'Masakazu Hashimoto', NULL, '2025-08-22', '2025-09-30', 'posters/shin_1755655698.jpg', 'https://www.youtube.com/watch?v=lDBE5HetMQc', 'P', 'Lồng tiếng', 'Sau khi Lực lượng Phòng vệ Kasukabe giành được một chuyến đi đến Ấn Độ, Shinnosuke và Bo‑chan bước vào một cửa hàng tổng hợp đáng ngờ và phát hiện một chiếc ba lô chứa bí mật kinh hoàng.', 'active', '2025-08-19 19:08:18', '2025-08-19 19:08:18', NULL, '2D'),
(37, 16, 'BLOOD BROTHERS: ANH EM XƯƠNG MÁU', 130, 'Abhilash Chandra, Syafiq Yusof', 'Sharnaaz Ahmad, Shukri Yahaya', '2025-08-19', '2025-09-30', 'posters/referenceschemeheadofficeallowplaceholdertrueheight700ldapp-10-1_1755656507.jpg', NULL, 'T18', 'Phụ đề', 'Ghaz, vệ sĩ trung thành, bị cáo buộc phản bội ông chủ quyền lực và tìm đến em trai Jaki để cùng minh oan. Họ phải đối mặt với thế giới ngầm đầy mưu mô, nguy hiểm để bảo vệ danh dự và tình thân.', 'active', '2025-08-19 19:21:47', '2025-08-19 19:21:47', NULL, '3D'),
(38, 18, 'TOGETHER: DÍNH LẸO', 102, 'Michael Shanks', 'Alison Brie, Dave Franco', '2025-08-15', '2025-09-30', 'posters/referenceschemeheadofficeallowplaceholdertrueheight700ldapp-3_1755657502.jpg', 'https://www.youtube.com/watch?v=c1KQ67n3VsI', 'T18', 'Phụ đề', 'Nhiều năm sau trong mối quan hệ của mình, Tim và Millie đứng trước ngã rẽ khi họ chuyển đến vùng quê. Khi căng thẳng đã bắt đầu tăng cao, một thế lực phi thường xuất hiện đe dọa phá hủy cuộc sống, tình yêu và thân xác của họ.', 'active', '2025-08-19 19:24:54', '2025-08-20 00:56:34', NULL, '2D'),
(39, 19, 'MY DAUGHTER IS A ZOMBIE: ZOMBIE CƯNG CỦA BA', 107, 'Pil Kam-sung', 'Cho Jung-seok , Lee Jung-eun , Cho Yeo-jeong , Yoon Kyung-ho , Choi Yu-ri', '2025-08-15', '2025-09-30', 'posters/referenceschemeheadofficeallowplaceholdertrueheight700ldapp-1_1755656913.jpg', NULL, 'T13', 'Phụ đề', 'Lee Jeong Hwan – một huấn luyện viên động vật nghiêm khắc – sống cùng cô con gái tuổi teen nổi loạn đam mê nhảy múa, Lee Su A. Một ngày nọ, Su A bị nhiễm virus zombie đang lan rộng khắp thế giới.', 'active', '2025-08-19 19:28:33', '2025-08-19 19:28:33', NULL, '2D');
